// Package abi is the C ABI's implementation on Go types (docs/extension-api.md §6): the handle
// table, the buffer convention, the panic guard, the codec and the body of every base export. An
// archive — the generic one in ./ffi, or a product's — is a `main` package of thin //export
// wrappers over the functions below, generated by ffi/gen, plus the product's own exports.
//
// The entry points take the C arguments as Go values: each pointer as unsafe.Pointer, each length
// as int64, and they answer the status as an int32 the wrapper converts back. Every buffer rule —
// bounds, truncation, the no-partial-document answer — lives here, once, for every archive.

var (
	registeredMu         sync.Mutex
	registeredExtensions []extension.Extension
)

// Register sets the extensions every later Open attaches. A product archive calls it from its
// main package's init, before any caller can reach an export; it is the archive's static set.
func Register(exts ...extension.Extension) {
	registeredMu.Lock()
	defer registeredMu.Unlock()
	registeredExtensions = append(registeredExtensions, exts...)
}

func registered() []extension.Extension {
	registeredMu.Lock()
	defer registeredMu.Unlock()
	return append([]extension.Extension(nil), registeredExtensions...)
}

// Lookup resolves a handle token ic_lj_open issued, so a product's own exports act on the same open
// forest the base exports do.
func Lookup(h uint64) (*embedded.Handle, bool) { return lookupHandle(h) }

// AbiVersion is ic_lj_abi_version.
func AbiVersion() uint32 { return uint32(baseAbiVersion()) }

// Echo is ic_lj_echo.
func Echo(in unsafe.Pointer, inLen int64, out unsafe.Pointer, outCap int64, outLen unsafe.Pointer) int32 {
	return int32(baseEcho(C.lj_cstr(in), C.int64_t(inLen), (*C.char)(out), C.int64_t(outCap), (*C.int64_t)(outLen)))
}

// Open is ic_lj_open.
func Open(req unsafe.Pointer, reqLen int64, outHandle unsafe.Pointer) int32 {
	return int32(baseOpen(C.lj_cstr(req), C.int64_t(reqLen), (*C.lj_handle_t)(outHandle)))
}

// Adopt is ic_lj_adopt.
func Adopt(req unsafe.Pointer, reqLen int64) int32 {
	return int32(baseAdopt(C.lj_cstr(req), C.int64_t(reqLen)))
}

// Close is ic_lj_close.
func Close(h uint64) int32 { return int32(baseClose(C.lj_handle_t(h))) }

// dataOp is the shape every data export shares.
type dataOp func(C.lj_handle_t, C.lj_cstr, C.int64_t, *C.char, C.int64_t, *C.int64_t) C.lj_status_t

func call(op dataOp, h uint64, req unsafe.Pointer, reqLen int64, out unsafe.Pointer, outCap int64, outLen unsafe.Pointer) int32 {
	return int32(op(C.lj_handle_t(h), C.lj_cstr(req), C.int64_t(reqLen), (*C.char)(out), C.int64_t(outCap), (*C.int64_t)(outLen)))
}

