func NodeCreate(h uint64, req unsafe.Pointer, reqLen int64, out unsafe.Pointer, outCap int64, outLen unsafe.Pointer) int32 {
	return call(baseNodeCreate, h, req, reqLen, out, outCap, outLen)
}

